CREATE TABLE IF NOT EXISTS quality_spec(spec_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,material_or_product_id TEXT NOT NULL,stage TEXT NOT NULL,spec_name TEXT NOT NULL,parameter_code TEXT NOT NULL,unit TEXT,min_value NUMERIC,max_value NUMERIC,required BOOLEAN NOT NULL DEFAULT TRUE,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_sampling_plan(plan_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,stage TEXT NOT NULL,plan_name TEXT NOT NULL,sample_qty NUMERIC NOT NULL DEFAULT 1,frequency TEXT NOT NULL DEFAULT 'BATCH',active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_inspection(inspection_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,stage TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'HOLD',sample_qty NUMERIC NOT NULL DEFAULT 1,coa_no TEXT,remarks TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_result(result_id TEXT PRIMARY KEY,inspection_id TEXT NOT NULL,parameter_code TEXT NOT NULL,value_text TEXT,value_numeric NUMERIC,unit TEXT,pass BOOLEAN NOT NULL,remarks TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_nc(nc_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,inspection_id TEXT,category TEXT NOT NULL,severity TEXT NOT NULL DEFAULT 'MAJOR',description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_capa(capa_id TEXT PRIMARY KEY,nc_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,root_cause TEXT,corrective_action TEXT,preventive_action TEXT,due_date DATE,status TEXT NOT NULL DEFAULT 'OPEN',owner_user_id TEXT,closed_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quality_declaration(declaration_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,product_id TEXT NOT NULL,allergen_code TEXT NOT NULL,contains BOOLEAN NOT NULL DEFAULT TRUE,statement TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_quality_batch ON quality_inspection(organization_id,entity_id,batch_id,status);
